contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test entry
    // params: amount to deposit and a receiver address to deposit for
    function run(uint256 amount, address receiver) public payable {
        require(receiver != address(0));

        // Observe initial state
        uint256 beforeUserBalance = c.usdcBalance(receiver);
        uint256 beforeRoundBalance = c.roundUsdcBalance();
        uint256 beforeRound = c.currentRound();

        // We call depositUsdc from this contract (msg.sender for c will be this test contract)
        // The function transferFrom will be attempted; as the test cannot provide ERC20 approvals,
        // depositUsdc may revert. We capture whether it reverted.
        bool reverted;
        try c.depositUsdc(amount, receiver) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after-state (always via public getters)
        uint256 afterUserBalance = c.usdcBalance(receiver);
        uint256 afterRoundBalance = c.roundUsdcBalance();
        uint256 afterRound = c.currentRound();

        // General invariant to assert:
        // If call reverted => balances unchanged and round unchanged
        // If call succeeded => user's usdcBalance increased by exactly amount and round balance increased by exactly amount,
        //   and currentRound did not change (depositUsdc shouldn't increment round)
        assert(
            (reverted && afterUserBalance == beforeUserBalance && afterRoundBalance == beforeRoundBalance && afterRound == beforeRound)
            ||
            (!reverted && afterUserBalance == beforeUserBalance + amount && afterRoundBalance == beforeRoundBalance + amount && afterRound == beforeRound)
        );
    }

    receive() external payable {}
}

