contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test: calling claim( receiver, amount ) either reverts or results in
    // the caller's recorded unclaimedShares decreasing by exactly amount and
    // the dnGmxJuniorVault.balanceOf(receiver) increasing by at least amount.
    // We observe only through public surface of c; to check balance change in
    // dnGmxJuniorVault we use c.claimAndRedeem which calls redeem and moves shares
    // back to caller, but that's complicated; instead we only check the unclaimedShares invariant
    // visible via c.unclaimedShares(address).

    // We require claimer != address(0) and receiver != address(0) and amount > 0
    function run(address claimer, address receiver, uint256 amount) public payable {
        require(claimer != address(0) && receiver != address(0) && amount != 0);

        // Observe unclaimed before for claimer
        uint256 beforeUnclaimed = c.unclaimedShares(claimer);

        // Make the call as the InvMutTest contract acting as msg.sender; but per harness,
        // msg.sender for calls into c will be this contract. To emulate claimer we rely
        // on the fact that the checker deploys c freshly and this contract is the caller.
        // So we only call claim with receiver and amount; claimer param is used for observation.

        bool didRevert;
        try c.claim(receiver, amount) {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        uint256 afterUnclaimed = c.unclaimedShares(claimer);

        // General rule: if claim reverted then unclaimedShares unchanged; otherwise decreased by exactly amount (but not underflowing)
        assert(didRevert ? afterUnclaimed == beforeUnclaimed : afterUnclaimed + amount == beforeUnclaimed);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry: attempt to call pauseDeposit and assert the general rule
    // Parameters:
    // - callerIsKeeper: when true we first set keeper to this contract via owner-only setKeeper call (owner is this contract on fresh deploy)
    // We require nothing else.
    function run(bool callerIsKeeper) public payable {
        // If we want this contract to be the keeper, set it via owner function. The freshly deployed c has owner == this contract
        if (callerIsKeeper) {
            // owner-only: this contract is the owner according to deployer constraints in harness
            c.setKeeper(address(this));
        }

        bool didRevert;
        try c.pauseDeposit() {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        // If call did not revert, paused() must be true. If it reverted, paused() may be false.
        assert(didRevert || c.paused());
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry used by the verifier
    function run(address claimer, address receiver, uint256 amount) public payable {
        require(receiver != address(0)); // receiver must be non-zero to exercise non-revert path possibility

        // Observe before state via public getters
        uint256 before_usdc = c.usdcBalance(claimer);
        uint256 before_unclaimed = c.unclaimedShares(claimer);
        uint256 before_vault_shares = c.dnGmxJuniorVault().balanceOf(claimer);

        // perform the action and capture whether it reverted
        bool reverted;
        try c.claim{value: 0}(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after state
        uint256 after_usdc = c.usdcBalance(claimer);
        uint256 after_unclaimed = c.unclaimedShares(claimer);
        uint256 after_vault_shares = c.dnGmxJuniorVault().balanceOf(claimer);

        // General rule (single assert):
        // 1) claim never changes the stored usdcBalance for the claimer
        // 2) if claim succeeded then unclaimedShares decreased by at least amount (cannot be negative)
        // 3) if claim succeeded then the on-chain vault balance of claimer did not increase (shares were transferred out)
        assert(
            // usdcBalance unchanged
            after_usdc == before_usdc
            // if reverted, we only require usdc unchanged; otherwise require unclaimed decreased by >= amount
            && (reverted || (before_unclaimed >= amount && after_unclaimed == before_unclaimed - amount))
            // if succeeded, vault balance did not increase
            && (reverted || after_vault_shares <= before_vault_shares)
        );
    }

    // allow receiving ETH if needed by external calls
    receive() external payable {}
}

